async (page) => {
  const paths = ["/about/","/academics/","/life-at-michigan/","/athletics/","/research/","/health-medicine/","/initiatives/","/giving/","/prospective-students/","/current-students/","/faculty-staff/","/parents/","/alumni/","/schools-colleges/"];
  const extractor = () => {
    const abs = u => { try { return new URL(u, location.href).pathname; } catch { return u; } };
    const out = { route: location.pathname };
    const panel = document.querySelector('.panel');
    out.panelClass = panel ? panel.className : '';
    const ph = document.querySelector('.panel-header h2') || document.querySelector('.panel-header');
    out.title = ph ? ph.textContent.trim() : document.title.split('›')[0].trim();
    const desc = document.querySelector('.panel-description');
    out.description = desc ? desc.textContent.replace(/\s+/g,' ').trim() : '';
    const rec = nb => {
      const h = nb.querySelector('h3');
      const items = [...nb.querySelectorAll(':scope > div > ul > li')].map(li=>{
        const s = li.querySelector('summary');
        if (s) { const dc = s.parentElement.querySelector('.dropdown-content'); return {k:'d', label:s.textContent.trim(), children: dc ? [...dc.querySelectorAll('li')].map(x=>x.textContent.trim()) : []}; }
        const a = li.querySelector('a');
        if (a) return {k:'a', href:abs(a.getAttribute('href')), label:a.textContent.trim()};
        return {k:'p', label:li.textContent.replace(/\s+/g,' ').trim()};
      });
      return { title: h ? h.textContent.trim() : '', extraTitles: [...nb.querySelectorAll('h3')].slice(1).map(x=>x.textContent.trim()), items, paras: [...nb.querySelectorAll(':scope > div > p')].map(p=>p.textContent.replace(/\s+/g,' ').trim()) };
    };
    const all = [...document.querySelectorAll('.nav-block')];
    out.blocks = all.filter(nb=>!nb.closest('.secondary')).map(rec);
    out.secondaryBlocks = all.filter(nb=>nb.closest('.secondary')).map(rec);
    const feat = document.querySelector('.feature');
    if (feat) {
      const img = feat.querySelector('img');
      out.featureImg = img ? abs(img.getAttribute('src')) : '';
      const cap = feat.querySelector('.caption');
      if (cap) {
        const l = cap.querySelector('a');
        out.caption = [...cap.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join(' ').replace(/\s+/g,' ').trim();
        out.captionLink = l ? { href: abs(l.getAttribute('href')), label: l.textContent.trim() } : null;
      }
    }
    const sh = document.querySelector('.sharing');
    if (sh) { const img = sh.querySelector('img'); out.sharingImg = img ? abs(img.getAttribute('src')) : ''; out.sharingCaption = sh.querySelector('.sharing-caption p') ? sh.querySelector('.sharing-caption p').textContent.trim() : ''; }
    return out;
  };
  const results = {};
  for (const p of paths) {
    await page.goto('http://localhost:37557' + p, { waitUntil: 'domcontentloaded' });
    results[p] = await page.evaluate(extractor);
  }
  return JSON.stringify(results);
}

